#include <algorithm>
#include <array>
#include <cassert>
#include <cmath>
#include <ctime>
#include <fstream>
#include <iostream>
#include <map>
#include <numeric>
#include <set>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
using namespace std;
constexpr int N=1250, NN=1252, X=1250, Y=1251, T=1058;
using Adj=array<array<int,3>,NN>;
struct C {int p,e,g,h,orient,id;};
struct B {array<int,NN>d,par;int ecc;};
Adj src, a; vector<pair<int,int>> edges;
clock_t started; double softlimit;
double elapsed(){return double(clock()-started)/CLOCKS_PER_SEC;}
string ints(const vector<int>&v){ostringstream o;o<<'[';for(size_t i=0;i<v.size();i++){if(i)o<<',';o<<v[i];}o<<']';return o.str();}
B bfs(int root){B b;b.d.fill(-1);b.par.fill(-1);array<int,NN>q;int lo=0,hi=0;q[hi++]=root;b.d[root]=0;b.ecc=0;while(lo<hi){int u=q[lo++];for(int v:a[u])if(b.d[v]<0){b.d[v]=b.d[u]+1;b.par[v]=u;b.ecc=max(b.ecc,b.d[v]);q[hi++]=v;}}if(hi<NN)b.ecc=NN;return b;}
int bad(const B&b){for(int i=0;i<NN;i++)if(b.d[i]<0||b.d[i]>10)return i;return -1;}
vector<int> path(const B&b,int r,int t){vector<int>v;if(b.d[t]<0)return v;for(int z=t;z!=-1;z=b.par[z]){v.push_back(z);if(z==r)break;}reverse(v.begin(),v.end());return v;}
bool adjold(int u,int v){return find(src[u].begin(),src[u].end(),v)!=src[u].end();}
void del1(int u,int v){for(int&z:a[u])if(z==v){z=-1;return;}throw runtime_error("cut missing");}
void del(int u,int v){del1(u,v);del1(v,u);}
void add1(int u,int v){for(int&z:a[u])if(z<0){z=v;return;}throw runtime_error("add no port");}
void add(int u,int v){add1(u,v);add1(v,u);}
pair<vector<int>,vector<int>> build(const C&c){a=src;a[X].fill(-1);a[Y].fill(-1);del(0,1);del(869,1178);del(c.g,c.h);add(c.p,c.h);vector<int>xp={0,1178},yp={1,869};auto&pp=(c.p==0?xp:yp);replace(pp.begin(),pp.end(),c.p,c.g);for(int v:xp)add(X,v);for(int v:yp)add(Y,v);add(X,Y);set<int>s={0,1,869,1178,c.g,c.h,X,Y};for(int u:s){set<int>ss;for(int v:a[u]){if(v<0||v>=NN||v==u||!ss.insert(v).second||find(a[v].begin(),a[v].end(),u)==a[v].end())throw runtime_error("candidate local degree/simple/reciprocity contract");}}return{xp,yp};}
string edge_role(int u,int v,const C&c){if(min(u,v)==min(c.p,c.h)&&max(u,v)==max(c.p,c.h))return"repair";if((u==X&&v==Y)||(u==Y&&v==X))return"helper_xy";if((u==X&&v==1178)||(v==X&&u==1178))return"protected_x1178";if((u==c.g&&(v==X||v==Y))||(v==c.g&&(u==X||u==Y)))return"transferred_spoke";if(u>=N||v>=N)return"helper_spoke";return"retained_source";}
void witness(const string&f,const C&c,const string&stage,int r,int t,const B&b){ofstream o(f);auto p=path(b,r,t);o<<"{\"config_id\":"<<c.id<<",\"moved_pin\":"<<c.p<<",\"third_edge_id\":"<<c.e<<",\"g\":"<<c.g<<",\"h\":"<<c.h<<",\"stage\":\""<<stage<<"\",\"root\":"<<r<<",\"target\":"<<t<<",\"distance\":"<<b.d[t]<<",\"path\":"<<ints(p)<<",\"route_edge_roles\":[";for(size_t i=1;i<p.size();i++){if(i>1)o<<',';o<<'"'<<edge_role(p[i-1],p[i],c)<<'"';}o<<"]}\n";}
void savehit(const C&c,const vector<int>&xp,const vector<int>&yp,const vector<pair<int,int>>&stats){ofstream e("candidate1252.edges");e<<NN<<" 1878\n";for(int u=0;u<NN;u++)for(int v:a[u])if(u<v)e<<u<<' '<<v<<'\n';ofstream p("PARAMETERS.json");p<<"{\"n\":1252,\"m\":1878,\"max_degree\":3,\"frozen_object_id\":4536,\"third_edge_id\":"<<c.e<<",\"third_cut\":["<<c.g<<','<<c.h<<"],\"repair\":["<<c.p<<','<<c.h<<"],\"pins_x\":"<<ints(xp)<<",\"pins_y\":"<<ints(yp)<<",\"protected_edge\":[1250,1178],\"status\":\"PRODUCER_ALLROOT_PASS_PENDING_FRESH_ACCEPTANCE\"}\n";ofstream r("ALL_ROOT_STATS.tsv");r<<"root\teccentricity\n";for(auto z:stats)r<<z.first<<'\t'<<z.second<<'\n';}
int main(int argc,char**argv){started=clock();softlimit=argc>2?stod(argv[2]):14.;try{ifstream f(argv[1]);int n,m;if(!(f>>n>>m)||n!=N||m!=1875)throw runtime_error("source header");for(auto&row:src)row.fill(-1);for(int i=0;i<m;i++){int u,v;if(!(f>>u>>v)||u<0||u>=N||v<0||v>=N||u==v)throw runtime_error("source literal edge");if(u>v)swap(u,v);edges.push_back({u,v});auto fill=[&](int x,int y){for(int&z:src[x])if(z<0){z=y;return;}throw runtime_error("source degree>3");};fill(u,v);fill(v,u);}sort(edges.begin(),edges.end());if(unique(edges.begin(),edges.end())!=edges.end())throw runtime_error("duplicate source edge");for(int u=0;u<N;u++){for(int v:src[u])if(v<0)throw runtime_error("source degree<3");sort(src[u].begin(),src[u].end());}if(edges[0]!=make_pair(0,1)||edges[1515]!=make_pair(869,1178))throw runtime_error("frozen edge label binding");
set<int>pins={0,1,869,1178};int eligible=0;for(auto e:edges)if(!pins.count(e.first)&&!pins.count(e.second))eligible++;vector<C>all,pilot,rest;int cid=0;for(int p:{0,1,869})for(int e=0;e<m;e++){auto [u,v]=edges[e];if(pins.count(u)||pins.count(v))continue;for(int k=0;k<2;k++){int g=k?v:u,h=k?u:v;if(adjold(p,h))continue;C c{p,e,g,h,k,cid++};all.push_back(c);(g==T?pilot:rest).push_back(c);}}
{ofstream d("ACTUAL_DOMAIN.json");d<<"{\"source_parse_count\":1,\"source_validity_bfs\":0,\"n_source\":1250,\"m_source\":1875,\"simple_cubic_contract\":true,\"eligible_third_edges\":"<<eligible<<",\"legal_parameter_configs\":"<<all.size()<<",\"stage_a_configs\":"<<pilot.size()<<",\"config_id_order\":\"p=0,1,869; lex source edge; orientation0,1\"}\n";}
ofstream rows("CONFIG_RESULTS.tsv");rows<<"config_id\tstage\tmoved_pin\tthird_edge_id\tg\th\tx_to_saved_t\ty_to_saved_t\tx_to_1178\tx_to_withdrawn_pin\tfirst_bad_stage\tfirst_bad_root\tfirst_bad_target\tfirst_bad_distance\n";ofstream pilots("PILOT_PATHS.jsonl");long long xb=0,yb=0,ob=0,oldroots=0,done=0,xfail=0,yfail=0,oldfail=0,bothpass=0,p1ok=0,p3tests=0,p3ok=0,p3ref=0,savedxfix=0;map<int,int>stageap;bool hit=false,timed=false;bool first=false,firsty=false,firstold=false;vector<C>order=pilot;order.insert(order.end(),rest.begin(),rest.end());int cursor=-1;for(auto c:order){if(elapsed()>softlimit){timed=true;cursor=c.id;break;}bool isp=(c.g==T);auto [xp,yp]=build(c);B bx=bfs(X);xb++;int fx=bad(bx);if(bx.d[T]>=0&&bx.d[T]<=10)savedxfix++;int fy=-2;B by;bool ytested=false;if(isp||fx<0){by=bfs(Y);yb++;fy=bad(by);ytested=true;}if(isp){bool ok=bx.d[1178]==1&&by.d[1178]<=2&&by.d[1178]>=0&&bx.d[T]<=2&&bx.d[T]>=0&&by.d[T]<=2&&by.d[T]>=0;p1ok+=ok;stageap[c.p]++;pilots<<"{\"config_id\":"<<c.id<<",\"p\":"<<c.p<<",\"third\":["<<c.g<<','<<c.h<<"],\"x_to_withdrawn\":"<<bx.d[c.p]<<",\"x_withdrawn_path\":"<<ints(path(bx,X,c.p))<<",\"x_to_saved_t\":"<<bx.d[T]<<",\"y_to_saved_t\":"<<by.d[T]<<",\"x_to_1178\":"<<bx.d[1178]<<",\"y_to_1178\":"<<by.d[1178]<<",\"P1_pass\":"<<(ok?"true":"false")<<"}\n";if(c.p==0||c.p==1){p3tests++;if(bx.d[c.p]<0||bx.d[c.p]>10)p3ok++;else{p3ref++;witness("P3_REFUTATION.json",c,"PILOT_WITHDRAWN_PIN",X,c.p,bx);}}}
string failstage;int fr=-1,ft=-1,fd=-1;if(fx>=0){xfail++;failstage="NEW_X";fr=X;ft=fx;fd=bx.d[fx];if(!first){witness("FIRST_FAILURE.json",c,failstage,fr,ft,bx);first=true;}}else if(fy>=0){yfail++;failstage="NEW_Y";fr=Y;ft=fy;fd=by.d[fy];if(!firsty){witness("FIRST_OTHERHELPER_FAILURE.json",c,failstage,fr,ft,by);firsty=true;}if(!first){witness("FIRST_FAILURE.json",c,failstage,fr,ft,by);first=true;}}else{bothpass++;vector<pair<int,int>>stats={{X,bx.ecc},{Y,by.ecc}};bool oldok=true;for(int r=0;r<N;r++){if(elapsed()>softlimit){timed=true;cursor=c.id;oldok=false;failstage="BUDGET_DURING_OLDROOTS";break;}B br=bfs(r);ob++;oldroots++;stats.push_back({r,br.ecc});int fb=bad(br);if(fb>=0){oldok=false;oldfail++;failstage="OLD_OLD";fr=r;ft=fb;fd=br.d[fb];if(!firstold){witness("FIRST_OLDOLD_FAILURE.json",c,failstage,r,fb,br);firstold=true;}if(!first){witness("FIRST_FAILURE.json",c,failstage,r,fb,br);first=true;}break;}}if(oldok){hit=true;failstage="FULL_ALLROOT_PASS";savehit(c,xp,yp,stats);}}
rows<<c.id<<'\t'<<(isp?"A_SAVED_TARGET":"B_FULL_REMAINDER")<<'\t'<<c.p<<'\t'<<c.e<<'\t'<<c.g<<'\t'<<c.h<<'\t'<<bx.d[T]<<'\t'<<(ytested?by.d[T]:-2)<<'\t'<<bx.d[1178]<<'\t'<<bx.d[c.p]<<'\t'<<failstage<<'\t'<<fr<<'\t'<<ft<<'\t'<<fd<<'\n';done++;if(hit||timed)break;}
rows.close();pilots.close();ofstream o("NUMERIC_RESULT.json");o<<"{\"status\":\""<<(hit?"FOUND_PENDING_INDEPENDENT_ACCEPTANCE":timed?"UNKNOWN_BUDGET":"COMPLETE_NO_FIXED_FROZEN_BASE_TRANSFER")<<"\",\"eligible_third_edges\":"<<eligible<<",\"domain_configs\":"<<all.size()<<",\"stage_a_configs\":"<<pilot.size()<<",\"visited_configs\":"<<done<<",\"next_or_partial_config_id\":"<<cursor<<",\"new_x_bfs\":"<<xb<<",\"new_y_bfs\":"<<yb<<",\"modified_oldroot_bfs\":"<<ob<<",\"new_x_fail\":"<<xfail<<",\"new_y_fail_after_x_pass\":"<<yfail<<",\"both_newroot_pass\":"<<bothpass<<",\"oldold_fail_candidates\":"<<oldfail<<",\"saved_t_new_x_repaired_configs\":"<<savedxfix<<",\"P1_pilot_pass\":"<<p1ok<<",\"P3_pilot_tests\":"<<p3tests<<",\"P3_pilot_supported\":"<<p3ok<<",\"P3_refutations\":"<<p3ref<<",\"source_parse_count\":1,\"source_validity_bfs\":0,\"producer_cpu_seconds\":"<<elapsed()<<",\"hit\":"<<(hit?"true":"false")<<"}\n";cout<<"status="<<(hit?"FOUND":timed?"UNKNOWN":"COMPLETE_NO")<<" configs="<<done<<'/'<<all.size()<<" both="<<bothpass<<" oldfail="<<oldfail<<" CPU="<<elapsed()<<endl;return 0;}catch(const exception&e){ofstream o("NUMERIC_ERROR.txt");o<<e.what()<<'\n';cerr<<e.what()<<endl;return 2;}}
